<?php
 namespace QQWorld\Setup\Test\Unit\Model\Cron; use QQWorld\Framework\ObjectManagerInterface; use QQWorld\Setup\Model\Cron\ComponentUninstallerFactory; use QQWorld\Setup\Model\Cron\JobComponentUninstall; use QQWorld\Framework\Composer\ComposerInformation; class JobComponentUninstallTest extends \PHPUnit\Framework\TestCase { private $job; private $output; private $status; private $updater; private $objectManager; private $objectManagerProvider; private $moduleUninstallHelper; private $themeUninstallHelper; private $composerInformation; private $quence; public function setUp() { $this->output = $this->getMockForAbstractClass( \Symfony\Component\Console\Output\OutputInterface::class, [], '', false ); $this->status = $this->createMock(\QQWorld\Setup\Model\Cron\Status::class); $this->moduleUninstallHelper = $this->createMock(\QQWorld\Setup\Model\Cron\Helper\ModuleUninstall::class); $this->themeUninstallHelper = $this->createMock(\QQWorld\Setup\Model\Cron\Helper\ThemeUninstall::class); $this->composerInformation = $this->createMock(\QQWorld\Framework\Composer\ComposerInformation::class); $this->objectManagerProvider = $this->createMock(\QQWorld\Setup\Model\ObjectManagerProvider::class); $this->objectManager = $this->getMockForAbstractClass( \QQWorld\Framework\ObjectManagerInterface::class, [], '', false ); $packageInfoFactory = $this->createMock(\QQWorld\Framework\Module\PackageInfoFactory::class); $packageInfo = $this->createMock(\QQWorld\Framework\Module\PackageInfo::class); $packageInfoFactory->expects($this->any())->method('create')->willReturn($packageInfo); $this->objectManagerProvider->expects($this->any())->method('get')->willReturn($this->objectManager); $this->updater = $this->createMock(\QQWorld\Setup\Model\Updater::class); $this->quence = $this->createPartialMock(\QQWorld\Setup\Model\Cron\Queue::class, ['addJobs']); } private function setUpUpdater() { $this->updater->expects($this->any())->method('createUpdaterTask')->willReturn(''); } private function setUpQuence() { $this->quence->expects($this->once())->method('addJobs'); } public function testExecuteModule() { $this->setUpUpdater(); $this->setUpQuence(); $this->moduleUninstallHelper->expects($this->once()) ->method('uninstall') ->with($this->output, 'vendor/module-package', true); $this->job = new JobComponentUninstall( $this->composerInformation, $this->moduleUninstallHelper, $this->themeUninstallHelper, $this->objectManagerProvider, $this->output, $this->quence, $this->status, $this->updater, 'setup:component:uninstall', [ 'components' => [ [ JobComponentUninstall::COMPONENT_NAME => 'vendor/module-package', ] ], 'dataOption' => 'true' ] ); $this->composerInformation->expects($this->once()) ->method('getInstalledQQWorldPackages') ->willReturn(['vendor/module-package' => ['type' => ComposerInformation::MODULE_PACKAGE_TYPE]]); $this->job->execute(); } public function testExecuteLanguage() { $this->setUpUpdater(); $this->setUpQuence(); $this->composerInformation->expects($this->once()) ->method('getInstalledQQWorldPackages') ->willReturn(['vendor/language-a' => ['type' => ComposerInformation::LANGUAGE_PACKAGE_TYPE]]); $this->moduleUninstallHelper->expects($this->never())->method($this->anything()); $this->themeUninstallHelper->expects($this->never())->method($this->anything()); $this->job = new JobComponentUninstall( $this->composerInformation, $this->moduleUninstallHelper, $this->themeUninstallHelper, $this->objectManagerProvider, $this->output, $this->quence, $this->status, $this->updater, 'setup:component:uninstall', [ 'components' => [ [ JobComponentUninstall::COMPONENT_NAME => 'vendor/language-a', ] ] ] ); $this->job->execute(); } public function testExecuteTheme() { $this->setUpUpdater(); $this->setUpQuence(); $this->composerInformation->expects($this->once()) ->method('getInstalledQQWorldPackages') ->willReturn(['vendor/theme-a' => ['type' => ComposerInformation::THEME_PACKAGE_TYPE]]); $this->themeUninstallHelper->expects($this->once()) ->method('uninstall') ->with($this->output, 'vendor/theme-a'); $this->moduleUninstallHelper->expects($this->never())->method($this->anything()); $this->job = new JobComponentUninstall( $this->composerInformation, $this->moduleUninstallHelper, $this->themeUninstallHelper, $this->objectManagerProvider, $this->output, $this->quence, $this->status, $this->updater, 'setup:component:uninstall', [ 'components' => [ [ JobComponentUninstall::COMPONENT_NAME => 'vendor/theme-a', ] ] ] ); $this->job->execute(); } public function testExecuteUnknownType() { $this->setUpUpdater(); $this->composerInformation->expects($this->once()) ->method('getInstalledQQWorldPackages') ->willReturn(['vendor/unknown-a' => ['type' => 'unknown']]); $this->moduleUninstallHelper->expects($this->never())->method($this->anything()); $this->themeUninstallHelper->expects($this->never())->method($this->anything()); $this->job = new JobComponentUninstall( $this->composerInformation, $this->moduleUninstallHelper, $this->themeUninstallHelper, $this->objectManagerProvider, $this->output, $this->quence, $this->status, $this->updater, 'setup:component:uninstall', [ 'components' => [ [ JobComponentUninstall::COMPONENT_NAME => 'vendor/unknown-a', ] ] ] ); $this->job->execute(); } public function testExecuteWrongFormat(array $params) { $this->moduleUninstallHelper->expects($this->never())->method($this->anything()); $this->themeUninstallHelper->expects($this->never())->method($this->anything()); $this->job = new JobComponentUninstall( $this->composerInformation, $this->moduleUninstallHelper, $this->themeUninstallHelper, $this->objectManagerProvider, $this->output, $this->quence, $this->status, $this->updater, 'setup:component:uninstall', $params ); $this->job->execute(); } public function executeWrongFormatDataProvider() { return [ 'empty' => [[]], 'no name' => [['components' => [['key' => 'value']]]], 'components not array' => [['components' => '']], ]; } public function testExecuteUpdateFails() { $this->updater->expects($this->once())->method('createUpdaterTask')->willReturn('error'); $this->composerInformation->expects($this->once()) ->method('getInstalledQQWorldPackages') ->willReturn(['vendor/language-a' => ['type' => ComposerInformation::LANGUAGE_PACKAGE_TYPE]]); $this->job = new JobComponentUninstall( $this->composerInformation, $this->moduleUninstallHelper, $this->themeUninstallHelper, $this->objectManagerProvider, $this->output, $this->quence, $this->status, $this->updater, 'setup:component:uninstall', [ 'components' => [ [ JobComponentUninstall::COMPONENT_NAME => 'vendor/language-a', ] ] ] ); $this->job->execute(); } } 